//! Rust add-ons for the buoy's Meshtastic firmware (Heltec V3 / ESP32-S3).
//!
//! Layout:
//! - `app` — plain Rust logic. No FFI, no unsafe; unit-testable on the laptop.
//! - `ffi` — the C ABI the C++ Meshtastic module calls (header generated by cbindgen).
//! - `esp` — ESP32-only glue: global allocator (ESP-IDF heap) and panic handler.
//!
//! On the ESP32 this crate is `no_std` + `alloc`. On the host (`cargo test`) it uses `std`.
#![cfg_attr(target_os = "none", no_std)]

extern crate alloc;

pub mod app;
pub mod ffi;

#[cfg(target_os = "none")]
mod esp;
